   279	/** @brief 旋转的实际实现（公开入口只负责计时探针，测完删）。 */
   280	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   281	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   282	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   283	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy);
   284	
   285	/**
   286	 * @brief RGB565 整层旋转：把 `src` 绕 (pivot_x, pivot_y) 转 `angle10`（0.1°）后，
   287	 *        让这个 pivot 落在 `dst` 的 (dst_cx, dst_cy)。
   288	 *
   289	 * @details 摆法照抄 LVGL 适配层（`lv_epic_setup_layers` + `lv_draw_sifli_epic_img`）：
   290	 *          bg = 目的整层，fg = 源整层 + `transform_cfg`，两者在**同一个坐标空间**里，
   291	 *          fg 的 `x_offset/y_offset` 决定"源的左上角摆在哪" ⇒ 让 pivot 落在
   292	 *          (dst_cx,dst_cy) 就是 `offset = dst_c - pivot`。pivot 按 HAL 注释是
   293	 *          "base on VideoLayer's origin"，即**源缓冲的像素坐标**。
   294	 *
   295	 * @note 同步（包装底下是 polling 版 HAL），返回时硬件已停。
   296	 * @note 源先 clean、目的按行 invalidate（PSRAM 写回缓存的前提）。
   297	 * @return true = 已执行；false = 两种：① 参数越界/硬件不可用，**什么都没做**；
   298	 *         ② **执行超时**（`EPIC_WaitDone` 超时）—— 这一种 R 可能已被写了**一部分**，
   299	 *         调用方必须把目的缓冲当成"脏的"，重新烘一次整幅，不能沿用上一帧。
   300	 */
   301	bool myvendor_epic_rotate(const uint16_t * src_buf, uint32_t src_stride,
   302	  int32_t src_w, int32_t src_h, uint16_t * dst_buf, uint32_t dst_stride,
   303	  int32_t dst_w, int32_t dst_h, int32_t angle10, int32_t pivot_x,
   304	  int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
   305	{
   306	  if (!myvendor_epic_ready() || src_buf == NULL || dst_buf == NULL)
   307	    {
   308	      return false;
   309	    }
   310	
   311	  /* 【临时探针】旋转耗时统计（[vrot]，LOG_DEBUG，`ctl log all` 可见）。测完删。 */
   312	  {
   313	    static struct
   314	    {
   315	      uint32_t n;
   316	      uint32_t sum;
   317	      uint32_t max;
   318	      uint32_t win;
   319	    } pf;
   320	    uint32_t t0 = clock_systime_ticks();
   321	    bool r = myvendor_epic_rotate_impl(src_buf, src_stride, src_w, src_h,
   322	      dst_buf, dst_stride, dst_w, dst_h, angle10, pivot_x, pivot_y, dst_cx,
   323	      dst_cy);
   324	    uint32_t ms = (uint32_t)(clock_systime_ticks() - t0);
   325	    uint32_t win;
   326	
   327	    if (pf.win == 0u)
   328	      {
   329	        pf.win = clock_systime_ticks();
   330	      }
   331	    if (r)
   332	      {
   333	        pf.n++;
   334	        pf.sum += ms;
   335	        if (ms > pf.max)
   336	          {
   337	            pf.max = ms;
   338	          }
   339	      }
   340	    win = (uint32_t)(clock_systime_ticks() - pf.win);
   341	    if (win >= 2000u)
   342	      {
   343	        if (pf.n > 0u)
   344	          {
   345	            syslog(LOG_DEBUG, "[vrot] bakes n=%u avg=%ums max=%ums win=%ums",
   346	              (unsigned)pf.n, (unsigned)(pf.sum / pf.n), (unsigned)pf.max,
   347	              (unsigned)win);
   348	          }
   349	        pf.n = 0u;
   350	        pf.sum = 0u;
   351	        pf.max = 0u;
   352	        pf.win = clock_systime_ticks();
   353	      }
   354	    return r;
   355	  }
   356	}
