   358	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   359	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   360	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   361	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
   362	{
   363	  EPIC_LayerConfigTypeDef layers[2];
   364	  EPIC_LayerConfigTypeDef out;
   365	  bool ok;
   366	  const uint32_t wt_before = g_epic_wait_timeouts;
   367	
   368	  if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
   369	      || angle10 < 0 || angle10 >= 3600)
   370	    {
   371	      return false;
   372	    }
   373	
   374	  /* 坐标寄存器 10 bit（EPIC_COORDINATES_MAX = 1010），越界 HAL 会断言。 */
   375	  if (src_w > EPIC_COORDINATES_MAX || src_h > EPIC_COORDINATES_MAX
   376	      || dst_w > EPIC_COORDINATES_MAX || dst_h > EPIC_COORDINATES_MAX)
   377	    {
   378	      return false;
   379	    }
   380	
   381	  /* EPIC 绕过 CPU 缓存直读 PSRAM：先把源写回去。 */
   382	  lv_epic_clean_invalidate_cache_range(src_buf,
   383	    (size_t)src_stride * (size_t)src_h);
   384	
   385	  HAL_EPIC_LayerConfigInit(&layers[0]);          /* 背景 = 目的整层 */
   386	  layers[0].data = (uint8_t *)dst_buf;
   387	  layers[0].color_mode = EPIC_COLOR_RGB565;
   388	  layers[0].width = (uint16_t)dst_w;
   389	  layers[0].height = (uint16_t)dst_h;
   390	  layers[0].x_offset = 0;
   391	  layers[0].y_offset = 0;
   392	  layers[0].total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
   393	
   394	  HAL_EPIC_LayerConfigInit(&layers[1]);          /* 前景 = 源整层 + 变换 */
   395	  layers[1].data = (uint8_t *)src_buf;
   396	  layers[1].color_mode = EPIC_COLOR_RGB565;
   397	  layers[1].width = (uint16_t)src_w;
   398	  layers[1].height = (uint16_t)src_h;
   399	  layers[1].x_offset = (int16_t)(dst_cx - pivot_x);
   400	  layers[1].y_offset = (int16_t)(dst_cy - pivot_y);
   401	  layers[1].total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
   402	  layers[1].transform_cfg.angle = (uint16_t)angle10;
   403	  layers[1].transform_cfg.pivot_x = (int16_t)pivot_x;
   404	  layers[1].transform_cfg.pivot_y = (int16_t)pivot_y;
   405	  layers[1].transform_cfg.scale_x = EPIC_INPUT_SCALE_NONE;
   406	  layers[1].transform_cfg.scale_y = EPIC_INPUT_SCALE_NONE;
   407	
   408	  memcpy(&out, &layers[0], sizeof(out));
   409	
   410	  /*
   411	   * 超时也算失败：HAL 的 `EPIC_WaitDone()` 超时只把 `g_epic_wait_timeouts` 加一、
   412	   * 仍返回 HAL_OK。照 HAL_OK 收下会把"没转完的像素"当成功 —— 调用方
   413	   * （`vmap_rot_full`）据此认为 R 已更新，屏上就会停在半张旧图。
   414	   * 本文件其它搬运路径（copy/fill）一直用 `epic_result()` 兜这件事，旋转也接上。
   415	   */
   416	  ok = epic_result(wt_before, lv_epic_blend(layers, 2, &out) == HAL_OK,
   417	    "rotate");
   418	
   419	  if (ok)
   420	    {
   421	      epic_invalidate_rect_rows(dst_buf, dst_stride, dst_w, dst_h);
   422	    }
   423	
   424	  return ok;
   425	}
