  1039	             * 失败（EPIC 超时/参数）要留恢复标志：`want_rot10` 与 `rot10` 一旦相等、
  1040	             * 又没有帧外增量，service 下一拍就会早退，屏上永远停在半张图。
  1041	             * 置 `rot_pending` 后每拍都会重试整幅，直到成功为止。
  1042	             */
  1043	            view->rot_pending = true;
  1044	        }
  1045	    }
