  1048	/**
  1049	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
  1050	 */
  1051	static void vmap_rot_track(vmap_view_t * view)
  1052	{
  1053	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1054	    const double c = cos(th);
  1055	    const double s = sin(th);
  1056	    const double dpx = view->pan_dx - view->r_pan_x;
  1057	    const double dpy = view->pan_dy - view->r_pan_y;
  1058	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
  1059	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
  1060	    const int32_t lim = view->r_margin - VMAP_ROT_TRACK_GUARD;
  1061	
  1062	    if (view->rot10 != view->r_rot10
  1063	        || abs((int)sx) > lim || abs((int)sy) > lim) {
  1064	        if (!vmap_rot_full(view)) {    /* 角度变了、或余量用完了 */
  1065	            /* 同 service：失败必须留下重试记账，否则停车后没有任何东西再触发重烘。 */
  1066	            view->rot_pending = true;
  1067	        }
  1068	        return;
  1069	    }
  1070	
  1071	    vmap_rot_place(view, sx, sy);
  1072	}
