  1074	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
  1075	{
  1076	    lv_coord_t px;
  1077	    lv_coord_t py;
  1078	
  1079	    if (!view || !view->canvas) {
  1080	        return;
  1081	    }
  1082	
  1083	    px = (lv_coord_t)lround(dx);
  1084	    py = (lv_coord_t)lround(dy);
  1085	
  1086	    if (px == view->last_pan_px && py == view->last_pan_py) {
  1087	        return;
  1088	    }
  1089	
  1090	    /*
  1091	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
  1092	     * GNSS movement; the centered arrow still updates normally.
  1093	     */
  1094	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
  1095	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
  1096	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
  1097	        return;
  1098	    }
  1099	
  1100	    view->pan_dx = (double)px;
  1101	    view->pan_dy = (double)py;
  1102	    view->last_pan_px = px;
  1103	    view->last_pan_py = py;
  1104	    view->map_rev++;
  1105	    vmap_label_collector_set_focus(&view->label_col,
  1106	        view->w / 2 + px, view->h / 2 + py);
  1107	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
  1108	    bicycle_inval_probe_tag("vmap_pan");
  1109	#endif
  1110	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
  1111	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
  1112	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
  1113	    if (!view->heading_up) {
  1114	        lv_obj_set_pos(view->canvas,
  1115	            (lv_coord_t)(-view->margin - px),
  1116	            (lv_coord_t)(-view->margin - py + view->y_bias));
  1117	        return;
  1118	    }
  1119	
  1120	    /*
  1121	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
  1122	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
  1123	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
  1124	     */
  1125	    vmap_rot_track(view);
  1126	}
