  1128	/**
  1129	 * @brief 航向朝上：地图跟随骑行方向旋转（箭头恒指上）。
  1130	 */
  1131	void vmap_view_set_heading_up(vmap_view_t * view, bool enable)
  1132	{
  1133	    if (!view || view->heading_up == enable) {
  1134	        return;
  1135	    }
  1136	
  1137	    if (enable && (view->rcanvas == NULL || view->rbuf == NULL)) {
  1138	        syslog(LOG_WARNING,
  1139	            "[map] heading-up refused: rotated buffer unavailable\n");
  1140	        return;
  1141	    }
  1142	
  1143	    view->heading_up = enable;
  1144	    view->heading_valid = false;
  1145	    view->rot10 = 0;
  1146	    view->want_rot10 = 0;
  1147	    view->r_rot10 = -1;         /* 强制下一次 track 重烘 */
  1148	    view->rot_pending = false;  /* 切换时会立刻重烘，旧的记账作废 */
  1149	
  1150	    if (enable) {
  1151	        if (view->rcanvas) {
  1152	            lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1153	        }
  1154	        if (view->canvas) {
  1155	            lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1156	        }
