  1159	        }
  1160	    } else {
  1161	        if (view->rcanvas) {
  1162	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1163	        }
  1164	        if (view->canvas) {
  1165	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1166	        }
  1167	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
  1168	        {
  1169	            int32_t i;
  1170	
  1171	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1172	                if (view->rot_label[i] != NULL) {
  1173	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1174	                }
  1175	            }
  1176	            view->rot_label_n = 0;
  1177	        }
