  1180	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
  1181	    view->last_pan_px = INT32_MIN;
  1182	    view->last_pan_py = INT32_MIN;
  1183	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
  1184	    syslog(LOG_NOTICE, "[map] heading-up %s\n", enable ? "on" : "off");
  1185	
  1186	    /* 首帧之前不要提前开帧（开机还没进过地图时由页面层控制）。 */
  1187	    if (view->render_rev != 0u) {
  1188	        vmap_view_render(view);
  1189	    }
  1190	}
