  1223	/**
  1224	 * @brief 更新航向（0–360，正北 0，顺时针）与当前速度。
  1225	 */
  1226	void vmap_view_set_heading(vmap_view_t * view, float heading_deg, float speed_kph)
  1227	{
  1228	    double d = (double)heading_deg;
  1229	    int32_t target;
  1230	    int32_t delta;
  1231	
  1232	    if (!view || !view->canvas) {
  1233	        return;
  1234	    }
  1235	    if (!view->heading_up) {
  1236	        return;
  1237	    }
  1238	    if (!(d >= 0.0) || !(d < 360.0)) {
  1239	        /* NaN / 越界：角度不动，但帧外增量的记账照样要服务。 */
  1240	        vmap_rot_service(view);
  1241	        return;
  1242	    }
  1243	
  1244	    if (!view->heading_valid) {
  1245	        /* 首个航向无条件接受：否则停车时箭头指上、地图还是正北。 */
  1246	        view->heading_deg = d;
  1247	        view->heading_valid = true;
  1248	    } else if (speed_kph >= VMAP_ROT_MIN_KPH) {
  1249	        double diff = d - view->heading_deg;
  1250	
  1251	        /* 圆周低通：先把差值折到 -180..180，避免 359°→1° 绕一整圈。 */
  1252	        while (diff > 180.0) {
  1253	            diff -= 360.0;
  1254	        }
  1255	        while (diff < -180.0) {
  1256	            diff += 360.0;
  1257	        }
  1258	        view->heading_deg += diff * (double)VMAP_ROT_SMOOTH;
  1259	        while (view->heading_deg >= 360.0) {
  1260	            view->heading_deg -= 360.0;
  1261	        }
  1262	        while (view->heading_deg < 0.0) {
  1263	            view->heading_deg += 360.0;
  1264	        }
  1265	    } else {
  1266	        /* 低速：course 是噪声，保持上次朝向；增量仍要走服务拍。 */
  1267	        vmap_rot_service(view);
  1268	        return;
  1269	    }
  1270	
  1271	    /*
  1272	     * 航向朝上 ⇒ 地图转 -heading（顺时针为正）。
  1273	     * **只记账不立即烘**：`want_rot10` 是"待应用目标"，真正的应用与限频都在
  1274	     * `vmap_rot_service()` 里，并且和帧外增量合并到同一次重烘。
  1275	     * 每烘一次 ~138 ms（288×264，0.55 Mpx/s）；1° 步进时若不限频，3.6°/s 的弯道
  1276	     * 会有 3~4 次/秒（≈50% UI）。1200 ms ⇒ 最多 0.83 次/秒 —— 转弯时地图比真实
  1277	     * 航向慢半拍，单步会放大到 ~2°（用户 2026-10-28 接受"旋转慢一些"）。
  1278	     */
  1279	    target = ((int32_t)lround(-view->heading_deg * 10.0) % 3600 + 3600) % 3600;
  1280	    delta = ((target - view->want_rot10 + 3600 + 1800) % 3600) - 1800;
  1281	    if (abs((int)delta) >= VMAP_ROT_STEP_10) {
  1282	        view->want_rot10 = target;
  1283	    }
  1284	
  1285	    vmap_rot_service(view);
  1286	}
